public static void runSpell(@Nonnull World world, @Nonnull ItemStack spellHolder, @Nonnull SpellData data) {
	if (world.isRemote) return;

	Entity caster = data.getCaster(world);
	if (caster instanceof EntityLivingBase && BaublesSupport.getItem((EntityLivingBase) caster, ModItems.CREATIVE_HALO, ModItems.FAKE_HALO, ModItems.REAL_HALO).isEmpty())
		return;

	for (SpellRing spellRing : getSpellChains(spellHolder)) {
		spellRing.runSpellRing(world, data, false);
	}
}

public static void runSpell(@Nonnull World world, @Nonnull List<SpellRing> chains, @Nonnull SpellData data) {
	if (world.isRemote) return;

	Entity caster = data.getCaster(world);
	if ((data.getData(SpellData.DefaultKeys.CAPABILITY) == null) || (caster instanceof EntityPlayer && BaublesSupport.getItem((EntityLivingBase) caster, ModItems.CREATIVE_HALO, ModItems.FAKE_HALO, ModItems.REAL_HALO).isEmpty()))
		return;

	for (SpellRing spellRing : chains) {
		spellRing.runSpellRing(world, data, false);
	}
}

/**
 * Gets all SpellRings that exist in an ItemStack with the children of each ring inside
 * of them, compressed essentially.
 * This basically returns the head of each spellData chain only.

package com.teamwizardry.wizardry.asm;

import com.teamwizardry.wizardry.api.events.*;
import net.minecraft.entity.Entity;
import net.minecraft.entity.EntityLivingBase;
import net.minecraft.entity.MoverType;
import net.minecraft.entity.player.EntityPlayer;
import net.minecraftforge.common.MinecraftForge;

/**
 * Created by Demoniaque.
 */
public class WizardryASMHooks {

	public static boolean playerClipEventHook(boolean hasNoClip, EntityPlayer player) {
		PlayerClipEvent event = new PlayerClipEvent(hasNoClip, player);
		MinecraftForge.EVENT_BUS.post(event);

		return event.noClip;
	}

	public static EntityMoveEvent entityPreMoveHook(Entity entity, MoverType type, double x, double y, double z) {
		EntityMoveEvent event = new EntityMoveEvent(entity, type, x, y, z);
		MinecraftForge.EVENT_BUS.post(event);
		return event;
	}

	public static EntityTravelEvent travel(EntityLivingBase entity, float strafe, float vertical, float forward) {
		EntityTravelEvent event = new EntityTravelEvent(entity, strafe, vertical, forward);
		MinecraftForge.EVENT_BUS.post(event);
		return event;
	}

	public static boolean entityRenderShadowAndFire(Entity entity) {
		EntityRenderShadowAndFireEvent event = new EntityRenderShadowAndFireEvent(entity);
		MinecraftForge.EVENT_BUS.post(event);
		return !event.override;
	}

	public static float slipperyHook(float prev, Entity entity) {
		SlipperinessEvent event = new SlipperinessEvent(entity, prev);
		MinecraftForge.EVENT_BUS.post(event);
		return event.getSlipperiness();
	}
}

